    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int n = k;
    int[] freq = new int[n];
    for (int num : arr) {
        int r = ((num % n) + n) % n;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= n / 2; r++) {
        int complement = n - r;
        if (r == complement) { // when n is even and r == n/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

