    int insertions = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                insertions++; // need an opening bracket before this
            } else {
                balance--; // match with an existing opening bracket
            }
        }
    }
    // any remaining unmatched opening brackets need closing brackets
    return insertions + balance;
}

