public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEndingHere = nums[0];
    int maxSoFar = nums[0];
    int minEndingHere = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        maxEndingHere = Math.max(num, maxEndingHere + num);
        maxSoFar = Math.max(maxSoFar, maxEndingHere);
        minEndingHere = Math.min(num, minEndingHere + num);
        minSoFar = Math.min(minSoFar, minEndingHere);
    }
    return Math.max(maxSoFar, Math.abs(minSoFar));
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int sz = fib.size();
        int next = fib.get(sz - 1) + fib.get(sz - 2);
        if (next > k) break;
        fib.add(next);
    }

    int count = 0;
    int remaining = k;
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.reverse(large);
    java.util.List<Integer> allFactors = new java.util.ArrayList<>(small);
    allFactors.addAll(large);
    if (k <= allFactors.size()) {
        return allFactors.get(k - 1);
    } else {
        return -1;
    }
}

