private void dfs(String s, int index, java.util.HashSet<String> set, int count, int[] max) {
    if (index == s.length()) {
        if (count > max[0]) max[0] = count;
        return;
    }
    for (int i = index; i < s.length(); i++) {
        String sub = s.substring(index, i + 1);
        if (!set.contains(sub)) {
            set.add(sub);
            dfs(s, i + 1, set, count + 1, max);
            set.remove(sub);
        }
    }
}

