public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    for (int i = 0; i <= n; i++) {
        int h = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && h < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int k = 0; k <= m + n - 2; k++) {
        int startRow = Math.max(0, k - (n - 1));
        int endRow = Math.min(m - 1, k);
        if ((k & 1) == 0) {
            for (int i = endRow; i >= startRow; i--) {
                result[index++] = mat[i][k - i];
            }
        } else {
            for (int i = startRow; i <= endRow; i++) {
                result[index++] = mat[i][k - i];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    return Integer.parseInt(new String(digits));
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    char[] arr = new char[n];
    char[][] pairs = { {'0','0'}, {'1','1'}, {'8','8'}, {'6','9'}, {'9','6'} };
    backtrack(0, n, arr, result, pairs);
    return result;
}

static void backtrack(int pos, int n, char[] arr, List<String> res) {
    if (pos >= (n+1)/2) {
        res.add(new String(arr));
        return;
    }
    for each pair (a,b) in mapping:
        if (pos==0 && n>1 && a=='0') continue;
        if (pos==n-1-pos) {
            if (a!=b) continue;
            arr[pos]=a;
        } else {
            arr[pos]=a;
            arr[n-1-pos]=b;
        }
        backtrack(pos+1, n, arr, res);
    }

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    // Check for duplicate points
    if ((p1[0] == p2[0] && p1[1] == p2[1]) ||
        (p1[0] == p3[0] && p1[1] == p3[1]) ||
        (p2[0] == p3[0] && p2[1] == p3[1])) {
        return false;
    }
    // Compute cross product to check collinearity
    int cross = (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0]);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> res = new java.util.ArrayList<>();
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 1; i <= 9 && i <= n; i++) {
        stack.push(i);
        while (!stack.isEmpty()) {
            int cur = stack.pop();
            res.add(cur);
            for (int j = 9; j >= 0; j--) {
                int next = cur * 10 + j;
                if (next <= n) {
                    stack.push(next);
                }
            }
        }
    }
    return res;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    result.append(word.reverse());
    return result.toString();
}
